bankorbust.css:
html[data-theme=dark].bgaext_bright .bga-cards_card > .bga-cards_card-sides > .bga-cards_card-side {
  filter: var(--ext-bright);
}
html[data-theme=dark].bgaext_dark .player-table {
  position: relative;
  isolation: isolate;
  background-image: none;
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .player-table::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background-image: var(--back-main);
  background-size: inherit;
  background-position: inherit;
  background-repeat: inherit;
  filter: invert(1) hue-rotate(180deg);
}

fadenfroh.css:
html[data-theme=dark].bgaext_bright .fadenfroh_card,
html[data-theme=dark].bgaext_bright .fadenfroh_round_overview_board,
html[data-theme=dark].bgaext_bright .fadenfroh_scoring_card_face {
  filter: var(--ext-bright);
}
html[data-theme=dark].bgaext_dark {
  --ff-section-bg: #00000060;
  --palette-main-bg: var(--ext-game-back);
}
html[data-theme=dark].bgaext_dark .fadenfroh_player_display_name {
  text-shadow: none;
}

snakesladders.css:
html[data-theme=dark].bgaext_dark {
  --ext-overall-color: #0008;
  --tile-light: var(--dark-20);
  --tile-alt: var(--dark-40);
  --accent-start: #0f5729;
  --accent-end: #052861;
}
html[data-theme=dark].bgaext_dark .board-container {
  color: var(--light-70);
}
